// clang-format on
inline const Record* Find(std::string_view name) {
    for (const auto& e : kRegistry)
        if (e.name == name)
            return &e;
    return nullptr;
}
inline const Record* Find(Game game, uint32_t id) {
    for (const auto& e : kRegistry)
        if (e.game == game && e.id == id)
            return &e;
    return nullptr;
}
inline const Record* Reverse(const Record& e) {
    return Find(e.reverse);
}
